const usuario = $input.first().json;

// Frases
const frases = $('Buscar Frases2').all();
const fraseDica       = frases[0]?.json?.Dica ?? 'Continue avançando!';
const fraseInspiracao = frases[0]?.json?.Historia ?? fraseDica;

// Parse tarefas por dia
let tarefasPorDia = [];
try { tarefasPorDia = JSON.parse(usuario.tarefas_por_dia || '[]'); } catch(e) {}

// Mapa dow → total (0=Dom,1=Seg...6=Sáb)
const mapa = {};
if (Array.isArray(tarefasPorDia)) {
  tarefasPorDia.forEach(d => { mapa[d.dow] = Number(d.total) || 0; });
}

// Chart: Seg(1) Ter(2) Qua(3) Qui(4) Sex(5) Sáb(6) Dom(0)
const chartData = [1,2,3,4,5,6,0].map(dow => mapa[dow] || 0);

// Datas com conclusão
const datasCompletas = (usuario.datas_completas || '')
  .split(',')
  .map(d => d.trim())
  .filter(Boolean);

// Maior sequência consecutiva da semana
const semanaInicio = new Date(usuario.semana_inicio + 'T00:00:00-03:00');
let maiorSequencia = 0;
let sequenciaAtual = 0;

for (let i = 0; i < 7; i++) {
  const d = new Date(semanaInicio);
  d.setDate(semanaInicio.getDate() + i);
  const dataStr = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(d);

  if (datasCompletas.includes(dataStr)) {
    sequenciaAtual++;
    if (sequenciaAtual > maiorSequencia) maiorSequencia = sequenciaAtual;
  } else {
    sequenciaAtual = 0;
  }
}

const diasSeguidos = maiorSequencia;

// Período formatado
const meses = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
const dtInicio = new Date(usuario.semana_inicio);
const dtFim    = new Date(usuario.semana_fim);
const periodo = `${String(dtInicio.getUTCDate()).padStart(2,'0')}-${String(dtFim.getUTCDate()).padStart(2,'0')} ${meses[dtFim.getUTCMonth()]} ${dtFim.getUTCFullYear()}`;

return [{ json: {
  phone:               usuario.phone,
  primeiro_nome:       usuario.primeiro_nome || 'Você',
  tarefas_completadas: Number(usuario.tarefas_completadas) || 0,
  dias_usando:         Number(usuario.dias_usando) || 0,
  dias_seguidos:       diasSeguidos,
  chart_data:          chartData,
  frase_dica:          fraseDica,
  frase_inspiracao:    fraseInspiracao,
  periodo,
} }];

const d = $input.first().json;

const nome         = d.primeiro_nome || 'Você';
const tarefas      = d.tarefas_completadas || 0;
const diasUsando   = d.dias_usando || 0;
const diasSeguidos = d.dias_seguidos || 0;
const periodo      = d.periodo || '';
const data         = d.chart_data || [0,0,0,0,0,0,0];

// --- LÓGICA DE CÁLCULO DO GRÁFICO (BARRAS EM HTML) ---
const labels = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'];
const maxData = Math.max(...data, 1);

// Arredonda o valor máximo do eixo Y para ser múltiplo de 3, criando 4 marcações harmoniosas
const maxY = maxData <= 3 ? 3 : Math.ceil(maxData / 3) * 3;
const yLabels = [maxY, Math.round(maxY * 2/3), Math.round(maxY / 3), 0];

// Gera as linhas e números do eixo Y
let yAxisHTML = '<div class="y-axis">';
yLabels.forEach(label => {
    yAxisHTML += `<div class="y-line"><span class="y-label">${label}</span><div class="y-grid-line"></div></div>`;
});
yAxisHTML += '</div>';

// Gera as barras do gráfico dinamicamente com base nas porcentagens
let barsHTML = '';
data.forEach((val, i) => {
    const heightPercent = (val / maxY) * 100;
    barsHTML += `
    <div class="bar-group">
        <div class="bar" style="height: ${heightPercent.toFixed(1)}%;"></div> 
        <span class="x-label">${labels[i]}</span>
    </div>`;
});
// -----------------------------------------------------

// Construção do HTML usando as variáveis
const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=1080, initial-scale=1.0">
    <title>Raio-X da Semana - Desafoga TDAH</title>
    <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">

    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; font-family: 'Nunito', sans-serif; }

        /* Ajuste do Body para remover completamente a borda escura e o padding */
        body { width: 1080px; height: 1350px; background-color: #fdfcff; margin: 0; padding: 0; }

        /* Ajuste do container para ocupar exatamente o tamanho da imagem, sem sombras vazando */
        .post-container { width: 1080px; height: 1350px; background-color: #fdfcff; position: relative; overflow: hidden; }

        .wave-bg { position: absolute; top: 0; left: 0; width: 100%; z-index: 1; }
        .content { position: relative; z-index: 2; padding: 70px 80px; display: flex; flex-direction: column; height: 100%; }
        .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 70px; }
        .header-text { max-width: 650px; margin-top: -10px; }
        .logo { display: flex; align-items: center; gap: 15px; font-size: 32px; font-weight: 800; color: #2b1d42; margin-bottom: 40px; }
        .logo i { color: #9271e8; font-size: 42px; }
        .title { font-size: 60px; font-weight: 800; color: #24163d; line-height: 1.2; margin-bottom: 10px; }
        .subtitle { font-size: 44px; font-weight: 600; color: #55496e; }
        .brain-mascot { position: absolute; top: 100px; right: 80px; width: 320px; height: auto; z-index: 3; }
        .section-title { font-size: 38px; font-weight: 800; color: #8c67d8; margin-bottom: 30px; }
        .cards-grid { display: flex; gap: 30px; margin-bottom: 60px; }
        .card { flex: 1; border-radius: 25px; padding: 35px 30px; display: flex; flex-direction: column; justify-content: center; }
        .card-icon { font-size: 38px; margin-bottom: 25px; }
        .card-data { display: flex; align-items: baseline; gap: 15px; }
        .card-number { font-size: 90px; font-weight: 900; line-height: 0.9; }
        .card-label { font-size: 26px; font-weight: 600; line-height: 1.2; max-width: 140px; }
        .card-purple { background-color: #e4d7f9; color: #4b3082; }
        .card-purple .card-icon { color: #4b3082; }
        .card-green { background-color: #d1f2eb; color: #126b58; }
        .card-green .card-icon { color: #126b58; }
        .card-orange { background-color: #ffe4cc; color: #a44813; }
        .card-orange .card-icon { color: #a44813; }
        .chart-container { background-color: #ffffff; border-radius: 25px; padding: 45px 50px; flex-grow: 1; display: flex; flex-direction: column; }
        .chart-title { font-size: 30px; font-weight: 800; color: #24163d; margin-bottom: 40px; }
        .chart-area { position: relative; flex-grow: 1; display: flex; align-items: flex-end; justify-content: space-between; padding-left: 50px; padding-bottom: 40px; }
        .y-axis { position: absolute; left: 0; top: 0; width: 100%; height: calc(100% - 40px); display: flex; flex-direction: column; justify-content: space-between; z-index: 1; }
        .y-line { display: flex; align-items: center; width: 100%; }
        .y-label { width: 40px; font-size: 20px; font-weight: 600; color: #6b5a8e; }
        .y-grid-line { flex-grow: 1; height: 1px; background-color: #e8e5f0; }
        .bar-group { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; height: 100%; justify-content: flex-end; width: 90px; }
        .bar { width: 100%; background-color: #9d7cf4; border-radius: 12px 12px 0 0; }
        .x-label { position: absolute; bottom: -40px; font-size: 20px; font-weight: 600; color: #6b5a8e; }
        .footer { text-align: center; margin-top: auto; padding-top: 40px; font-size: 24px; font-weight: 600; color: #55496e; }
    </style>
</head>
<body>

    <div class="post-container">
        <svg class="wave-bg" viewBox="0 0 1080 400" preserveAspectRatio="none" style="height: 400px;">
            <path d="M0,0 L1080,0 L1080,220 C950,220 880,140 750,150 C620,160 580,280 450,280 C320,280 250,200 120,200 C50,200 0,220 0,240 Z" fill="#e9e2f9"/>
            <path d="M0,0 L1080,0 L1080,250 C950,300 880,220 750,200 C620,180 580,320 450,320 C320,320 250,250 120,260 C50,265 0,300 0,310 Z" fill="#dcd1f5" opacity="0.6"/>
        </svg>

        <img src="https://res.cloudinary.com/degh1eojj/image/upload/v1775418675/Design_sem_nome__2_-removebg-preview_kwj79e.png" alt="Mascote Cérebro" class="brain-mascot">

        <div class="content">
            <div class="header">
                <div class="header-text">
                    <div class="logo">
                        <i class="fa-solid fa-head-side-virus"></i> Desafoga<br>TDAH
                    </div>
                    <h1 class="title">${nome},<br>Raio-X da Semana</h1>
                    <h2 class="subtitle">${periodo}</h2>
                </div>
            </div>

            <h3 class="section-title">Sua Semana em Números</h3>

            <div class="cards-grid">
                <div class="card card-purple">
                    <i class="fa-regular fa-circle-check card-icon"></i>
                    <div class="card-data">
                        <span class="card-number">${tarefas}</span>
                        <span class="card-label">Tarefas<br>Concluídas</span>
                    </div>
                </div>

                <div class="card card-green">
                    <i class="fa-regular fa-calendar card-icon"></i>
                    <div class="card-data">
                        <span class="card-number">${diasUsando}</span>
                        <span class="card-label">Dias<br>Ativos</span>
                    </div>
                </div>

                <div class="card card-orange">
                    <i class="fa-solid fa-fire card-icon"></i>
                    <div class="card-data">
                        <span class="card-number">${diasSeguidos}</span>
                        <span class="card-label">Sequência<br>Atual</span>
                    </div>
                </div>
            </div>

            <div class="chart-container">
                <h3 class="chart-title">Atividade Diária</h3>

                <div class="chart-area">
                    ${yAxisHTML}
                    ${barsHTML}
                </div>
            </div>

            <div class="footer">
                Você está no caminho certo, ${nome}! Continue focando. Sua jornada é incrível!
            </div>
        </div>
    </div>

</body>
</html>`;

// Monta o payload para envio
const apiPayload = {
    html: html,
    inline: true,
    fileName: "raio-x.png",
    options: {
        fullPage: true 
    }
};

return [{ 
    json: { 
        phone: d.phone, 
        primeiro_nome: nome, 
        html: html, 
        apiPayload: apiPayload 
    } 
}];

