// 1. Pega a data de entrada (o formato ISO 2026-04-19T15:12:41.000Z já é interpretado como UTC pelo JS)
const dataInteracao = new Date($json.last_interaction_at);

// 2. Pega o momento atual (sempre em UTC para garantir a base de comparação)
const agora = new Date();

// 3. Calcula a diferença em milissegundos
// 24 horas * 60 minutos * 60 segundos * 1000 milissegundos = 86.400.000
const diferencaMs = agora.getTime() - dataInteracao.getTime();
const vinteQuatroHorasMs = 24 * 60 * 60 * 1000;

// 4. Determina o resultado
const dentroDoPrazo = diferencaMs < vinteQuatroHorasMs && diferencaMs >= 0;

return {
  ...$json,
  dentroDoPrazo: dentroDoPrazo,
  diferencaHoras: (diferencaMs / (1000 * 60 * 60)).toFixed(2)
};
